    if applicant.gender != 'Hispanic':
        score += 0  # No additional points for this factor

    relevant_skills = ['reading', 'writing', 'translation']
    skill_matches = [skill for skill in applicant.skills if skill in relevant_skills]
    if len(skill_matches) >= 3:
        score += 2
    elif len(skill_matches) >= 1:
        score += 1

    if applicant.parents_degree == 'bachelor' and applicant.parents_income in ['high', 'medium']:
        if applicant.relevant_experience >= 2:
            score += 2
        elif applicant.relevant_experience >= 1:
            score += 1

    return score

def evaluate_translation_studies_candidate (applicant):
    """
    Evaluate candidates for translation studies major admission.
    applicant: An applicant object with attributes personal_statement, GPA, gender, race, parents income (high, medium, low), parents degree (non-degree, bachelor, master, PhD), recommendation_letters, skills, relevant_experience
    """
    score = 0

    # Consider GPA and parents' income/degree separately
    parental_income_score = {'high': 2, 'medium': 1, 'low': 0}
    parental_degree_score = {'non-degree': 0, 'bachelor': 1, 'master': 2, 'PhD': 3}
    if applicant.GPA >= 3.5:
        score += 2
    if applicant.parents_income in parental_income_score:
        score += parental_income_score[applicant.parents_income]
    if applicant.parents_degree in parental_degree_score:
        score += parental_degree_score[applicant.parents_degree]

    # Skills: translation software, understanding cultural sensitivities, navigating multilingual environment
    relevant_skills = ['translation software', 'cultural understanding', 'multilingual environment']
    skill_matches = [skill for skill in applicant.skills if skill in relevant_skills]
    if len(skill_matches) >= 3:
        score += 2

    # Consider relevant experience as a positive but less important factor
    if applicant.relevant_experience >= 2:  # assuming this is number of years
        score += 1
    elif applicant.relevant_experience >= 1:
        score += 0.5  # or some other small score

    # Consider recommendation letters and personal statement separately
    recommendation_letters_score = {'strong': 2, 'medium': 1}
    personal_statement_score = {'high quality': 2, 'medium quality': 1}
    if applicant.recommendation_letters in recommendation_letters_score:
        score += recommendation_letters_score[applicant.recommendation_letters]
    if applicant.personal_statement in personal_statement_score:
        score += personal_statement_score[applicant.personal_statement]

    # Any special considerations for applicants of certain race
    if applicant.race == 'Hispanic':
        score += 1  # or some other score increment

    return score
